// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the from address, a uint value, and an array of recipient addresses
    function testFuzz_property(address from, uint256 v, address[] memory tos) public {
        // admissible domain: tos must be non-empty (matches the require in transfer)
        vm.assume(tos.length > 0);

        // deploy a benign callee that always succeeds on the low-level call
        CalleeSuccess callee = new CalleeSuccess();

        // call transfer and capture its boolean return via try/catch to read actual behavior
        bool ok;
        try c.transfer(from, address(callee), tos, v) {
            ok = true; // call did not revert
        } catch {
            ok = false; // call reverted
        }

        // The reference contract always returns true (i.e., call completes without revert and returns true).
        // We assert that the call did not revert (ok == true). This will pass on the reference for all inputs
        // with non-empty tos, and fail on the mutant for some inputs because mutant returns false (call still
        // completes but our try block still considers it a non-revert; to observe the mutated false return value
        // we rely on the fact that the external call's success is the observed behavior: the mutant makes the
        // function return false while not reverting, but try/catch only detects reverts. To directly observe the
        // differing return value we instead perform a low-level staticcall to capture the boolean return.
        // However, per the test requirements we must assert a single property reading c's public surface. To
        // directly read the boolean return we perform the call via address(c).call and decode the returned data.

        // Perform the call via low-level call to capture the returned boolean value
        (bool success, bytes memory ret) = address(c).call(abi.encodeWithSelector(
            c.transfer.selector, from, address(callee), tos, v
        ));
        // call must succeed (no revert)
        assertTrue(success);

        // decode returned boolean and assert it is true (reference behavior)
        bool retval = abi.decode(ret, (bool));
        assertTrue(retval);
    }
}

// benign callee that always returns successfully from the encoded selector call
contract CalleeSuccess {
    // implement transferFrom(address,address,uint256) to simply return true (or do nothing)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
